-- =============================================================================
-- TIMELINE SEED — the story of everything, first pass (~130 entries).
-- Dates: negative numbers are BCE years as written (-753 = 753 BCE); deep time is simply
-- negative years (-66000000 = 66 million years ago). Deep-time dates are rounded
-- to accepted scientific estimates; human-history dates are the commonly
-- cited ones. Safe to re-run: upserts on slug.
-- =============================================================================

-- ---------------------------------------------------------------- regions
insert into public.regions (slug, name, lat, lng, sort_order, color_hex) values
  ('cosmos',          'The Cosmos',            0,   0, 0,  '#4a3d6b'),
  ('earth',           'The Whole Earth',       0,   0, 1,  '#8fae8b'),
  ('africa',          'Africa',                2,  20, 2,  '#f2a65a'),
  ('europe',          'Europe',               50,  12, 3,  '#7e9bc2'),
  ('middle-east',     'Middle East',          32,  42, 4,  '#e3b341'),
  ('south-asia',      'South Asia',           22,  78, 5,  '#f7a8a0'),
  ('east-asia',       'East Asia',            35, 110, 6,  '#e0685a'),
  ('southeast-asia',  'Southeast Asia',        5, 110, 7,  '#8fae8b'),
  ('central-asia',    'Central Asia',         44,  70, 8,  '#c98a4b'),
  ('north-america',   'North America',        42, -95, 9,  '#b7a9d6'),
  ('mesoamerica',     'Mesoamerica',          19, -96, 10, '#f6d68a'),
  ('south-america',   'South America',       -12, -70, 11, '#7fa36b'),
  ('oceania',         'Oceania & Pacific',   -20, 150, 12, '#9fc6e0')
on conflict (slug) do update set name = excluded.name, lat = excluded.lat, lng = excluded.lng, sort_order = excluded.sort_order, color_hex = excluded.color_hex;

-- ---------------------------------------------------------------- companions
update public.characters set curiosity_key = c.k
from (values ('crumb','fossil'),('mochi','wonder'),('toast','sprout'),('peach','muse'),('pickle','maker'),('butter','story'),('noodle','explorer'),('berri','muse')) as c(slug,k)
where public.characters.slug = c.slug;

-- ---------------------------------------------------------------- entries
-- Helper: one upsert statement for everything. Columns:
-- slug, kind, name, tagline, start, end, ongoing, precision, parent, level, region, lat, lng, importance, age_band, curiosity, what, where, why, color, icon
create temp table seed_entries (
  slug text, kind text, name text, tagline text, start_year double precision, end_year double precision, is_ongoing boolean,
  precision text, parent_slug text, level int, region_slug text, lat numeric, lng numeric, importance int, age_band int,
  curiosity_key text, what text, where_text text, why text, color_hex text, icon_key text
);

insert into seed_entries values
-- ===== ERAS, level 0: the broad story =====
('universe','era','The Universe','Everything, starting from a single hot moment.',-13800000000,null,true,'deep',null,0,'cosmos',null,null,3,1,'wonder','Space, time, matter and light all begin together about 13.8 billion years ago.','Everywhere. There was no "where" before this.','Every other thing on this timeline happens inside this one.','#4a3d6b','star'),
('earth','era','Earth','Our planet takes shape from dust and rock.',-4540000000,null,true,'deep','universe',0,'earth',null,null,3,1,'wonder','Earth forms from leftover material orbiting the young Sun.','The solar system, third rock from the Sun.','Everything alive that we know of has lived here.','#c98a4b','planet'),
('life','era','Life','Tiny living things appear in the oceans.',-3700000000,null,true,'deep','earth',0,'earth',null,null,3,1,'sprout','The first living cells appear less than a billion years after Earth forms.','In the oceans.','From these tiny beginnings comes every plant, animal and person.','#8fae8b','leaf'),
('complex-life','era','Complex Life','Bigger bodies, eyes, shells and legs.',-541000000,null,true,'deep','life',0,'earth',null,null,3,1,'fossil','Animals with hard parts, eyes and complex bodies spread through the seas, then onto land.','Oceans first, then land.','Most of the animal groups alive today begin here.','#7e9bc2','shell'),
('dinosaurs','era','Dinosaurs','Giants rule the land for over 160 million years.',-233000000,-66000000,false,'deep','complex-life',0,'earth',null,null,3,1,'fossil','Dinosaurs appear in the Triassic and dominate until an asteroid ends their reign.','Every continent, including Antarctica.','They lasted about 800 times longer than humans have existed so far.','#7fa36b','dino'),
('mammals','era','Age of Mammals','Furry, warm and clever, mammals take over.',-66000000,null,true,'deep','complex-life',0,'earth',null,null,3,1,'fossil','After the dinosaurs, mammals grow large and spread into every habitat.','Everywhere.','This is the era that eventually produces us.','#f2a65a','paw'),
('humans','era','Humans','Our own species, Homo sapiens.',-300000,null,true,'deep','mammals',0,'africa',null,null,3,1,'story','Homo sapiens appears in Africa and slowly spreads across the whole planet.','Africa first, then everywhere.','All of human history fits inside this thin slice of time.','#f7a8a0','person'),
('civilizations','era','Civilizations','Cities, writing, kings and roads.',-3500,null,true,'century','humans',0,'earth',null,null,3,1,'story','People gather in cities, invent writing and build the first states.','Mesopotamia, Egypt, the Indus, China, the Andes, Mesoamerica.','Written history, the part we can read for ourselves, begins here.','#e3b341','city'),
('modern-world','era','Modern World','Ships, machines, science and connection.',1500,null,true,'century','civilizations',0,'earth',null,null,3,1,'maker','Oceans are crossed, machines are built, science reshapes life, and the world becomes connected.','Everywhere.','Almost everything around you today was invented in this sliver of time.','#e0685a','gear'),
-- ===== ERAS, level 1: geologic eons and human ages =====
('hadean','era','Hadean','A molten, battered young Earth.',-4540000000,-4000000000,false,'deep','earth',1,'earth',null,null,2,2,'wonder','Earth is hot, volcanic and bombarded by rocks from space. The Moon forms.','Earth.','It shows how unrecognisable our planet once was.','#e0685a','fire'),
('archean','era','Archean','Oceans, continents and the first cells.',-4000000000,-2500000000,false,'deep','earth',1,'earth',null,null,2,2,'sprout','Oceans cover the planet, the first continents rise, and single-celled life appears.','Earth.','Life begins here and never stops.','#7e9bc2','wave'),
('proterozoic','era','Proterozoic','Oxygen fills the air. Cells get complicated.',-2500000000,-541000000,false,'deep','earth',1,'earth',null,null,2,2,'sprout','Tiny organisms fill the atmosphere with oxygen. Cells with a nucleus appear, then the first many-celled life.','Earth.','Without this oxygen, animals could never have evolved.','#b9c9db','bubble'),
('paleozoic','era','Paleozoic','Life explodes, then crawls onto land.',-541000000,-252000000,false,'deep','complex-life',1,'earth',null,null,2,2,'fossil','From the Cambrian explosion to the first forests and reptiles.','Earth.','Animals learn to live out of water.','#8fae8b','trilobite'),
('mesozoic','era','Mesozoic','The age of reptiles.',-252000000,-66000000,false,'deep','complex-life',1,'earth',null,null,2,2,'fossil','Dinosaurs, flying reptiles, sea reptiles and the first flowers and birds.','Earth.','Continents drift apart and life gets huge.','#7fa36b','dino'),
('cenozoic','era','Cenozoic','The age of mammals, right up to now.',-66000000,null,true,'deep','complex-life',1,'earth',null,null,2,2,'fossil','Mammals diversify, grasslands spread, ice ages come and go, humans appear.','Earth.','This is our era.','#f2a65a','paw'),
('paleolithic','era','Old Stone Age','Stone tools, fire, hunting and cave art.',-3300000,-9700,false,'deep','humans',1,'earth',null,null,2,2,'story','Humans and their relatives make stone tools, tame fire and spread across the world.','Africa, then Eurasia, Australia and the Americas.','The longest chapter of the human story by far.','#c98a4b','flint'),
('neolithic','era','Age of Farming','People plant seeds and settle down.',-9700,-3500,false,'approx','humans',1,'earth',null,null,2,2,'sprout','Farming begins in several places independently. Villages, pottery and the first monuments appear.','The Fertile Crescent, China, Mesoamerica, the Andes, New Guinea.','Farming makes cities possible.','#8fae8b','wheat'),
('bronze-age','era','Bronze Age','Metal tools, writing and the first empires.',-3300,-1200,false,'century','civilizations',1,'earth',null,null,2,2,'maker','People mix copper and tin into bronze. Writing, wheels and kingdoms spread.','Mesopotamia, Egypt, the Indus Valley, China, the Aegean.','It is the first age we can read about in people''s own words.','#e3b341','ingot'),
('iron-age','era','Iron Age','Stronger metal, bigger empires.',-1200,-500,false,'century','civilizations',1,'earth',null,null,2,2,'maker','Iron replaces bronze for tools and weapons. Alphabets, coins and large empires appear.','Across Afro-Eurasia.','Cheaper tools change farming and war.','#7a635a','anvil'),
('classical','era','Classical World','Greece, Rome, Persia, Han China, the Maya.',-800,500,false,'century','civilizations',1,'earth',null,null,2,2,'story','Philosophers, emperors, temples and long roads. Big ideas that still shape us.','Mediterranean, Persia, India, China, Mesoamerica.','Democracy, philosophy, and much of our maths and law start here.','#f6d68a','column'),
('post-classical','era','Medieval World','Trade routes, faiths and kingdoms across the globe.',500,1500,false,'century','civilizations',1,'earth',null,null,2,2,'story','Islam spreads, China prospers, empires rise in West Africa and the Andes, Vikings sail, the Mongols connect Asia.','Everywhere.','The world is more connected than people often imagine.','#b7a9d6','castle'),
('early-modern','era','Early Modern','Oceans crossed, printing, science.',1500,1800,false,'century','modern-world',1,'earth',null,null,2,2,'explorer','Ships link every continent, books spread, and science begins to explain the world.','Everywhere.','Global connection begins, with wonders and with terrible costs.','#9fc6e0','ship'),
('industrial','era','Industrial Age','Steam, factories, railways.',1760,1914,false,'decade','modern-world',1,'earth',null,null,2,2,'maker','Machines powered by steam and then electricity change how everything is made and moved.','Britain first, then the world.','Modern cities, work and travel begin here.','#7a635a','gear'),
('contemporary','era','Modern Era','From world wars to the internet.',1914,null,true,'year','modern-world',1,'earth',null,null,2,2,'maker','Two world wars, flight, space travel, computers and the internet.','Everywhere.','This is the world you were born into.','#e0685a','globe'),
-- ===== ERAS, level 2: geologic periods =====
('cambrian','era','Cambrian','An explosion of strange animals.',-541000000,-485000000,false,'deep','paleozoic',2,'earth',null,null,1,2,'fossil','Trilobites, early fish and creatures with eyes and legs appear in a geological blink.','Oceans.','Most major animal groups first show up here.','#8fae8b','trilobite'),
('ordovician','era','Ordovician','Seas full of life.',-485000000,-444000000,false,'deep','paleozoic',2,'earth',null,null,1,3,'fossil','Coral reefs, nautiloids and the first land plants.','Oceans and shorelines.','Ends with one of the great extinctions.','#7e9bc2','shell'),
('silurian','era','Silurian','Plants and bugs on land.',-444000000,-419000000,false,'deep','paleozoic',2,'earth',null,null,1,3,'sprout','Land plants spread and the first land animals, tiny arthropods, follow.','Land near water.','Land becomes liveable.','#9fc6e0','leaf'),
('devonian','era','Devonian','The age of fishes.',-419000000,-359000000,false,'deep','paleozoic',2,'earth',null,null,1,2,'fossil','Fish rule the seas and some grow legs. The first forests grow.','Oceans and swamps.','Our fishy ancestors walk out of the water.','#7e9bc2','fish'),
('carboniferous','era','Carboniferous','Giant forests and giant insects.',-359000000,-299000000,false,'deep','paleozoic',2,'earth',null,null,1,2,'sprout','Vast swampy forests grow, later becoming coal. Dragonflies the size of birds fly.','Swamps.','Today''s coal is these ancient forests.','#7fa36b','fern'),
('permian','era','Permian','One continent, then a catastrophe.',-299000000,-252000000,false,'deep','paleozoic',2,'earth',null,null,1,3,'fossil','All land joins into Pangaea. Reptiles thrive, then the worst extinction ever ends the period.','Pangaea.','Life nearly ends, then begins again.','#c98a4b','mountain'),
('triassic','era','Triassic','The first dinosaurs appear.',-252000000,-201000000,false,'deep','mesozoic',2,'earth',null,null,1,2,'fossil','After the great dying, reptiles recover. The first dinosaurs and first mammals appear.','Pangaea.','Both dinosaurs and mammals begin here, side by side.','#f2a65a','dino'),
('jurassic','era','Jurassic','Giants and the first birds.',-201000000,-145000000,false,'deep','mesozoic',2,'earth',null,null,1,2,'fossil','Long-necked sauropods, plated stegosaurs and the first birds.','Pangaea splits apart.','The dinosaur age most people picture.','#7fa36b','dino'),
('cretaceous','era','Cretaceous','Flowers, T. rex and an asteroid.',-145000000,-66000000,false,'deep','mesozoic',2,'earth',null,null,1,2,'fossil','Flowering plants spread, Tyrannosaurus hunts, and an asteroid ends it all.','Continents look almost modern.','Ends with the most famous extinction.','#8fae8b','flower'),
('paleogene','era','Paleogene','Mammals grow up.',-66000000,-23000000,false,'deep','cenozoic',2,'earth',null,null,1,3,'fossil','Small survivors of the extinction grow into whales, horses, primates and more.','Earth.','The mammal world takes shape.','#f2a65a','paw'),
('neogene','era','Neogene','Grasslands and apes.',-23000000,-2600000,false,'deep','cenozoic',2,'earth',null,null,1,3,'fossil','Grasslands spread, grazing animals thrive, and our ape ancestors start walking upright.','Earth, especially Africa.','Our family tree takes root.','#f6d68a','grass'),
('quaternary','era','Quaternary','Ice ages and humans.',-2600000,null,true,'deep','cenozoic',2,'earth',null,null,1,3,'fossil','Ice sheets advance and retreat. Humans evolve, spread, and change the planet.','Earth.','Our period.','#b9c9db','snow'),
-- ===== COSMIC AND EARLY EARTH EVENTS =====
('big-bang','event','The Big Bang','The beginning of space and time.',-13800000000,null,false,'deep',null,0,'cosmos',null,null,3,1,'wonder','The universe begins expanding from an unimaginably hot, dense state.','Everywhere at once.','It is the start of everything on this timeline.','#4a3d6b','star'),
('first-stars','event','The First Stars','Darkness ends.',-13600000000,null,false,'deep',null,0,'cosmos',null,null,3,1,'wonder','About 200 million years after the Big Bang, gravity pulls gas into the first stars and light fills the universe.','Early galaxies.','Stars make the elements we are made of.','#f6d68a','star'),
('milky-way','event','The Milky Way Takes Shape','Our home galaxy grows.',-13500000000,null,false,'deep',null,0,'cosmos',null,null,2,2,'wonder','Small galaxies merge and grow into the spiral we live in.','Our galaxy.','Our Sun forms inside it much later.','#b7a9d6','galaxy'),
('sun-forms','event','The Sun Forms','A cloud collapses into a star.',-4600000000,null,false,'deep',null,0,'cosmos',null,null,3,1,'wonder','A cloud of gas and dust collapses. The Sun ignites and leftover material forms planets.','The solar system.','No Sun, no Earth, no us.','#f6d68a','sun'),
('earth-forms','event','Earth Forms','Rocks collide and stick.',-4540000000,null,false,'deep',null,0,'earth',null,null,3,1,'wonder','Dust and rock clump together over millions of years into a planet.','Third from the Sun.','Home.','#c98a4b','planet'),
('moon-forms','event','The Moon Forms','A giant collision.',-4500000000,null,false,'deep',null,0,'earth',null,null,2,1,'wonder','A Mars-sized body crashes into Earth. The debris becomes the Moon.','Earth orbit.','The Moon steadies Earth''s tilt and makes the tides.','#f5ede2','moon'),
('oceans-form','event','The Oceans Form','Water covers the world.',-4400000000,null,false,'deep',null,0,'earth',null,null,2,1,'wonder','As Earth cools, water vapour rains down for millions of years and fills the oceans.','Earth.','Life will begin in this water.','#9fc6e0','wave'),
('first-life','organism','The First Life','Tiny cells in the sea.',-3700000000,null,false,'deep',null,0,'earth',null,null,3,1,'sprout','Single-celled microbes appear. We find their traces in very old rocks.','Ocean floors and shallow seas.','Every living thing descends from cells like these.','#8fae8b','cell'),
('great-oxidation','event','The Great Oxygenation','Microbes change the air.',-2400000000,null,false,'deep',null,0,'earth',null,null,2,2,'sprout','Cyanobacteria release oxygen for so long that the atmosphere fills with it.','Earth''s oceans and air.','Oxygen makes animals possible and turns the sky blue.','#9fc6e0','bubble'),
('first-eukaryotes','organism','Cells With a Nucleus','Cells get complicated.',-1800000000,null,false,'deep',null,0,'earth',null,null,2,3,'sprout','Cells with a nucleus and internal parts appear.','Oceans.','Plants, animals and fungi are all built from these cells.','#b7a9d6','cell'),
('ediacaran-biota','organism','Ediacaran Life','The first big soft creatures.',-575000000,null,false,'deep',null,0,'earth',null,null,1,3,'fossil','Strange soft-bodied organisms, some like quilted mattresses, live on the sea floor.','Oceans.','The first large multicellular life.','#b9c9db','leaf'),
('cambrian-explosion','event','The Cambrian Explosion','Animals everywhere, suddenly.',-538000000,null,false,'deep',null,0,'earth',null,null,3,1,'fossil','In a few tens of millions of years, most major animal groups appear, with eyes, shells, legs and teeth.','Oceans.','Complex animal life begins.','#8fae8b','trilobite'),
('first-fish','organism','The First Fish','Backbones arrive.',-525000000,null,false,'deep',null,0,'earth',null,null,2,2,'fossil','Small jawless fish are the first animals with a backbone.','Ancient seas.','All animals with backbones, including you, descend from them.','#7e9bc2','fish'),
('first-land-plants','organism','Plants Reach Land','Green spreads over rock.',-470000000,null,false,'deep',null,0,'earth',null,null,2,2,'sprout','Small moss-like plants grow on land for the first time.','Damp shorelines.','Land becomes green and liveable for animals.','#8fae8b','leaf'),
('first-insects','organism','The First Insects','Six legs on land.',-400000000,null,false,'deep',null,0,'earth',null,null,1,3,'fossil','The earliest insects appear among the first land plants.','Land.','Insects become the most numerous animals on Earth.','#7fa36b','bug'),
('tiktaalik','organism','Fish With Legs','A fish crawls out of water.',-375000000,null,false,'deep',null,0,'north-america',77,-91,3,1,'fossil','Tiktaalik has fins with wrist-like bones and can prop itself up in the shallows.','Found in Arctic Canada.','Life moves onto land.','#c98a4b','fish'),
('coal-forests','event','Giant Coal Forests','Trees taller than houses, insects bigger than birds.',-320000000,null,false,'deep',null,0,'earth',null,null,2,2,'sprout','Enormous swamp forests grow, die and become coal. Oxygen is high and insects grow huge.','Wet lowlands across Pangaea.','The fuel of the Industrial Age was made here.','#7fa36b','fern'),
('first-reptiles','organism','The First Reptiles','Eggs with shells.',-312000000,null,false,'deep',null,0,'earth',null,null,2,3,'fossil','Reptiles lay eggs that do not dry out, so they can live away from water.','Land.','Dinosaurs, birds and mammals all descend from early relatives of these.','#c98a4b','egg'),
('permian-extinction','extinction','The Great Dying','Life nearly ends.',-252000000,null,false,'deep',null,0,'earth',null,null,3,2,'fossil','Huge volcanic eruptions poison the air and seas. About 9 in 10 ocean species vanish.','Everywhere.','The worst extinction in Earth''s history, and the reset that let dinosaurs rise.','#e0685a','skull'),
('first-dinosaurs','organism','The First Dinosaurs','Small, fast and two-legged.',-233000000,null,false,'deep',null,0,'south-america',-29,-66,3,1,'fossil','The earliest dinosaurs are dog-sized runners.','Fossils from Argentina and Brazil.','The start of the dinosaur age.','#7fa36b','dino'),
('first-mammals','organism','The First Mammals','Tiny, furry and nocturnal.',-205000000,null,false,'deep',null,0,'earth',null,null,3,1,'fossil','Shrew-sized mammals scurry at night while dinosaurs rule the day.','Land.','Our ancestors lived alongside dinosaurs for 140 million years.','#f2a65a','paw'),
('sauropods','organism','The Giant Sauropods','The largest land animals ever.',-155000000,null,false,'deep',null,0,'earth',null,null,2,1,'fossil','Long-necked dinosaurs like Brachiosaurus grow longer than three buses.','Every continent.','Nothing on land has ever been bigger.','#7fa36b','dino'),
('archaeopteryx','organism','Archaeopteryx','A dinosaur with feathers and wings.',-150000000,null,false,'deep',null,0,'europe',49,11,2,2,'fossil','A crow-sized creature with teeth, claws and flight feathers.','Bavaria, Germany.','Birds are living dinosaurs, and this is the proof.','#b7a9d6','feather'),
('first-flowers','organism','The First Flowers','Colour comes to the world.',-130000000,null,false,'deep',null,0,'earth',null,null,2,2,'sprout','Flowering plants appear and spread with the help of insects.','Land.','Most plants you eat are flowering plants.','#f7a8a0','flower'),
('t-rex','organism','Tyrannosaurus rex','The tyrant lizard king.',-68000000,-66000000,false,'deep',null,0,'north-america',47,-107,3,1,'fossil','A 12-metre predator with teeth like bananas, alive only in the last 2 million years of the dinosaur age.','Western North America.','T. rex lived closer in time to you than to Stegosaurus.','#e0685a','dino'),
('asteroid-impact','extinction','The Asteroid Strikes','The dinosaurs'' age ends.',-66000000,null,false,'deep',null,0,'mesoamerica',21,-89,3,1,'fossil','A rock 10 kilometres wide hits the sea near Mexico. Dust blocks the Sun and most large animals die.','Chicxulub, Yucatán, Mexico.','It clears the way for mammals, and eventually for us.','#e0685a','comet'),
('early-primates','organism','The First Primates','Grasping hands and forward eyes.',-55000000,null,false,'deep',null,0,'earth',null,null,2,2,'fossil','Small tree-dwelling mammals with grasping hands appear.','Forests across the world.','The first members of our own branch.','#f2a65a','paw'),
('grasslands','event','Grasslands Spread','Open plains and grazing herds.',-20000000,null,false,'deep',null,0,'earth',null,null,1,3,'sprout','Grasses spread across continents, and herds of grazing animals follow.','Every continent.','Grass shapes horses, cattle, and later farming.','#f6d68a','grass'),
('lucy','organism','Lucy (Australopithecus)','An ancestor who walked upright.',-3200000,null,false,'deep',null,0,'africa',11,40,3,1,'fossil','A small, upright-walking ancestor whose skeleton was found in Ethiopia in 1974.','Ethiopia.','Walking on two legs came long before big brains.','#c98a4b','person'),
('first-stone-tools','invention','The First Stone Tools','Sharp edges from rock.',-3300000,null,false,'deep',null,0,'africa',3,36,3,1,'maker','Ancestors strike stones together to make cutting edges.','Kenya.','Tool-making begins, long before our species exists.','#7a635a','flint'),
('homo-erectus','organism','Homo erectus','The first long-distance traveller.',-1900000,-110000,false,'deep',null,0,'africa',0,36,2,2,'explorer','Tall, long-legged humans who spread from Africa as far as China and Java.','Africa and Asia.','The first humans to leave Africa.','#c98a4b','person'),
('control-of-fire','invention','Taming Fire','Warmth, light and cooked food.',-1000000,null,false,'deep',null,0,'africa',-26,27,3,1,'maker','Early humans learn to keep and use fire.','Southern Africa, among other places.','Cooking changes our bodies and our evenings.','#e0685a','fire'),
('neanderthals','organism','Neanderthals','Our close cousins.',-400000,-40000,false,'deep',null,0,'europe',44,0,2,2,'story','Stocky, strong humans who live in Europe and western Asia, make tools, use fire and bury their dead.','Europe and western Asia.','Many people today carry a little Neanderthal DNA.','#b7a9d6','person'),
('homo-sapiens','organism','Homo sapiens Appears','Us.',-300000,null,false,'deep',null,0,'africa',32,-5,3,1,'story','The earliest known fossils of our species are found in Morocco.','Africa.','Everyone alive today descends from these people.','#f7a8a0','person'),
('out-of-africa','event','Humans Spread Across the World','The great journey begins.',-68000,null,false,'deep',null,0,'africa',15,40,3,1,'explorer','Groups of Homo sapiens leave Africa and, over tens of thousands of years, reach every continent except Antarctica.','From Africa into Asia, Europe, Australia and the Americas.','This is how people came to live everywhere.','#f2a65a','footprints'),
('australia-settled','event','People Reach Australia','Crossing open sea.',-63000,null,false,'deep',null,0,'oceania',-12,133,2,2,'explorer','People cross stretches of ocean to reach Australia, one of the oldest continuous cultures on Earth.','Northern Australia.','Humans were seafarers far earlier than many imagine.','#f2a65a','boat'),
('cave-art','artwork','The Oldest Cave Paintings','Someone drew a pig on a wall.',-43000,null,false,'deep',null,0,'southeast-asia',-5,120,3,1,'muse','Hand stencils and animal paintings on cave walls in Sulawesi, Indonesia, and later at Chauvet in France.','Sulawesi, Indonesia.','The earliest art we know of.','#f7a8a0','paint'),
('americas-settled','event','People Reach the Americas','The last big continents.',-14000,null,false,'deep',null,0,'north-america',60,-150,2,2,'explorer','People move from Siberia into the Americas, along the coast and over land.','Alaska, then south.','Two whole continents gain people.','#f2a65a','footprints'),
