insert into public.timeline_entries
  (slug, kind, name, tagline, start_year, end_year, is_ongoing, precision, parent_slug, level, region_slug, lat, lng, importance, age_band, curiosity_key, what, where_text, why, color_hex, icon_key, status)
select slug, kind::public.timeline_kind, name, tagline, start_year, end_year, is_ongoing, precision, null, level, region_slug, lat, lng, importance, age_band, curiosity_key, what, where_text, why, color_hex, icon_key, 'active'
from seed_entries
on conflict (slug) do update set
  kind = excluded.kind, name = excluded.name, tagline = excluded.tagline, start_year = excluded.start_year, end_year = excluded.end_year,
  is_ongoing = excluded.is_ongoing, precision = excluded.precision, level = excluded.level, region_slug = excluded.region_slug,
  lat = excluded.lat, lng = excluded.lng, importance = excluded.importance, age_band = excluded.age_band, curiosity_key = excluded.curiosity_key,
  what = excluded.what, where_text = excluded.where_text, why = excluded.why, color_hex = excluded.color_hex, icon_key = excluded.icon_key, status = 'active';

-- Parents after all rows exist (self-referencing FK).
update public.timeline_entries e set parent_slug = s.parent_slug
from seed_entries s where e.slug = s.slug and s.parent_slug is not null;

-- ---------------------------------------------------------------- relations
insert into public.entry_relations (from_slug, to_slug, relation, note) values
  ('first-stars','sun-forms','led_to','Stars made the heavy elements the Sun and Earth are built from.'),
  ('great-oxidation','cambrian-explosion','led_to','Oxygen made big, active animals possible.'),
  ('permian-extinction','first-dinosaurs','led_to','Empty niches let dinosaurs rise.'),
  ('asteroid-impact','mammals','led_to','With the dinosaurs gone, mammals grew large.'),
  ('control-of-fire','homo-sapiens','led_to','Cooked food fed bigger brains.'),
  ('ice-age-ends','farming-begins','led_to','A warm, stable climate made farming possible.'),
  ('farming-begins','uruk','led_to','Surplus food fed the first cities.'),
  ('uruk','writing','led_to','Cities needed records.'),
  ('writing','alphabet','led_to','Simpler scripts followed complex ones.'),
  ('gutenberg','copernicus','led_to','Printing spread new ideas quickly.'),
  ('movable-type','gutenberg','inspired','Movable type was invented in China first.'),
  ('steam-engine','railway','led_to','Steam power on wheels.'),
  ('telegraph','telephone','led_to','Wires that carried dots and dashes soon carried voices.'),
  ('first-flight','moon-landing','led_to','Sixty-six years from Kitty Hawk to the Moon.'),
  ('personal-computer','world-wide-web','led_to','Computers on desks needed a way to connect.'),
  ('world-wide-web','smartphone','led_to','The web in every pocket.'),
  ('egypt-unified','norte-chico','overlapped','Pyramids were being built on two continents at once.'),
  ('roman-empire','han','overlapped','Two vast empires at opposite ends of the Silk Road.'),
  ('magna-carta','mongol-empire','overlapped','King John signed while Genghis Khan ruled Asia.'),
  ('leonardo','columbus','overlapped','Leonardo was forty when Columbus sailed.'),
  ('aztec','inca','overlapped','Two great American empires, unaware of each other.')
on conflict do nothing;

-- ---------------------------------------------------------------- adventures
insert into public.adventures (slug, name, tagline, description, curiosity_key, companion_character_slug, unlock_character_slug, start_entry_slug, steps, age_band, sort_order, status) values
  ('the-missing-bone', 'The Missing Bone', 'Crumb found a bone by the river. Whose is it?',
   'Follow a strange fossil back through time: work out what creature it belonged to, when it lived, what Earth looked like, who else was alive, and whether any humans were around to see it.',
   'fossil', 'crumb', 'crumb', 't-rex',
   '[{"title":"A strange bone","text":"Crumb found a bone as long as your arm. Bones this big belong to something enormous. Let''s find out when it lived.","entry_slug":"t-rex","companion_line":"I am not saying it is a monster. I am just saying it might be."},
     {"title":"How long ago?","text":"66 million years. Zoom out and find where that sits on the whole timeline. Notice how far it is from us.","entry_slug":"asteroid-impact","companion_line":"That is so far away I need to sit down."},
     {"title":"Who else was alive?","text":"Use What Else Was Happening to see who shared the world with T. rex: flowers, tiny mammals, and no people at all.","entry_slug":"first-flowers","companion_line":"No humans. Not one. I checked twice."},
     {"title":"Where were the humans?","text":"Slide forward to find the first humans. Count how many millions of years passed between the bone and the first person.","entry_slug":"homo-sapiens","companion_line":"So nobody ever saw a T. rex. That is a relief, honestly."},
     {"title":"Place it in your museum","text":"Add T. rex to your museum. It now has a home on your timeline.","entry_slug":"t-rex","companion_line":"We did it. I only worried about it a little."}]',
   1, 1, 'active'),
  ('the-lost-library', 'The Lost Library', 'Berri heard of a library where the whole world''s knowledge met.',
   'Travel to Baghdad in the year 830 and discover a house of scholars, then find out what was being written, built and invented elsewhere in the world at the same time.',
   'muse', 'berri', 'berri', 'house-of-wisdom',
   '[{"title":"A house of books","text":"In Baghdad, scholars are translating the wisdom of Greece, Persia and India. Find it on the timeline.","entry_slug":"house-of-wisdom","companion_line":"...so many books."},
     {"title":"What else was happening?","text":"Widen the view. Who else was writing, building and trading in the year 830?","entry_slug":"tang","companion_line":"Poets in China. Sailors in the north. Everyone at once."},
     {"title":"Where did the numbers come from?","text":"Go back a few centuries to India and find where the numbers we use were worked out.","entry_slug":"gupta","companion_line":"Zero. Someone had to invent nothing."},
     {"title":"Keep it","text":"Add the House of Wisdom to your museum.","entry_slug":"house-of-wisdom","companion_line":"I like it here. Can we stay a bit?"}]',
   2, 2, 'active'),
  ('the-first-city', 'The First City', 'Butter wants to know where the very first city was.',
   'Go back to a time before kings, find the first walls and temples, and discover the invention that made cities possible.',
   'story', 'butter', 'butter', 'uruk',
   '[{"title":"Before cities","text":"Start at the end of the Ice Age. The world warms. Find the first farmers.","entry_slug":"farming-begins","companion_line":"You have got this. Also, wheat."},
     {"title":"The first walls","text":"Slide forward to Uruk, maybe the biggest city on Earth 5,000 years ago.","entry_slug":"uruk","companion_line":"So many neighbours to cheer for."},
     {"title":"Cities elsewhere","text":"Use What Else Was Happening. Were there cities in other parts of the world too?","entry_slug":"norte-chico","companion_line":"Peru! At the same time! I did not know that."},
     {"title":"Keep it","text":"Add Uruk to your museum.","entry_slug":"uruk","companion_line":"Look at your museum grow."}]',
   1, 3, 'active'),
  ('across-the-pacific', 'Across the Pacific', 'Noodle has a canoe and a plan. Sort of.',
   'Sail with the greatest navigators in history and find out how people reached the most remote islands on Earth without maps or compasses.',
   'explorer', 'noodle', 'noodle', 'polynesia-hawaii',
   '[{"title":"Open ocean","text":"Find the moment Polynesians reached Hawaii, thousands of kilometres from anywhere.","entry_slug":"polynesia-hawaii","companion_line":"No map. Just stars and waves. Let''s go find out."},
     {"title":"The first crossing","text":"Go much further back. When did people first cross open sea?","entry_slug":"australia-settled","companion_line":"Sixty-five thousand years ago! People are amazing."},
     {"title":"The last land","text":"Slide forward to the last big land ever settled by people.","entry_slug":"aotearoa-settled","companion_line":"Aotearoa. I found a path. It is mostly ocean."},
     {"title":"Keep it","text":"Add the Hawaii voyage to your museum.","entry_slug":"polynesia-hawaii","companion_line":"Where next?"}]',
   2, 4, 'active'),
  ('when-humans-learned-to-write', 'When Humans Learned to Write', 'Toast would write it down if Toast were awake.',
   'Discover the first marks that held words, then follow writing across the world to the letters you are reading now.',
   'story', 'toast', 'toast', 'writing',
   '[{"title":"Marks in clay","text":"Find the first writing, pressed into wet clay in Mesopotamia.","entry_slug":"writing","companion_line":"Five more minutes. Then history."},
     {"title":"Pictures that talk","text":"Egyptians were writing around the same time. Use What Else Was Happening to see.","entry_slug":"egypt-unified","companion_line":"Writing in two places at once. Cosy."},
     {"title":"One sign, one sound","text":"Slide forward two thousand years to the first alphabet.","entry_slug":"alphabet","companion_line":"A, B, C... zzz."},
     {"title":"Books for everyone","text":"Jump to the printing press. Now everyone can read.","entry_slug":"gutenberg","companion_line":"Rest is a superpower. So is reading."},
     {"title":"Keep it","text":"Add the first writing to your museum.","entry_slug":"writing","companion_line":"Written down. Good."}]',
   1, 5, 'active'),
  ('the-story-of-everything', 'The Story of Everything', 'Mochi''s grand tour, from the first light to right now.',
   'A free adventure for everyone: zoom from the Big Bang to today in ten jumps and feel how the scale of time really works.',
   'wonder', 'mochi', null, 'big-bang',
   '[{"title":"The beginning","text":"Start at the very start.","entry_slug":"big-bang","companion_line":"Good things ahead! Literally everything, in fact."},
     {"title":"A home","text":"Nine billion years later, Earth forms.","entry_slug":"earth-forms","companion_line":"Look how far we came just to get to the start of Earth."},
     {"title":"Life","text":"Tiny cells in the sea.","entry_slug":"first-life","companion_line":"Small beginnings. My favourite kind."},
     {"title":"Giants","text":"Dinosaurs rule for 160 million years.","entry_slug":"sauropods","companion_line":"Longer than you can imagine. I tried."},
     {"title":"Us","text":"Humans appear. Notice how close to today this is.","entry_slug":"homo-sapiens","companion_line":"We are new here. Be kind to the place."},
     {"title":"Cities","text":"The first cities and writing.","entry_slug":"uruk","companion_line":"Neighbours! Stories! Bread!"},
     {"title":"Connected","text":"Ships cross the oceans.","entry_slug":"columbus","companion_line":"The world gets smaller and much more complicated."},
     {"title":"Machines","text":"Steam, trains, light.","entry_slug":"steam-engine","companion_line":"Everything speeds up from here."},
     {"title":"The Moon","text":"People stand on another world.","entry_slug":"moon-landing","companion_line":"Rain is sky confetti. The Moon is sky confetti you can stand on."},
     {"title":"You are here","text":"Right now. Everything came before this moment.","entry_slug":"today","companion_line":"And you are at the very end of the story so far. Good things ahead."}]',
   1, 0, 'active')
on conflict (slug) do update set name = excluded.name, tagline = excluded.tagline, description = excluded.description,
  curiosity_key = excluded.curiosity_key, companion_character_slug = excluded.companion_character_slug,
  unlock_character_slug = excluded.unlock_character_slug, start_entry_slug = excluded.start_entry_slug, steps = excluded.steps,
  age_band = excluded.age_band, sort_order = excluded.sort_order, status = excluded.status;

drop table if exists seed_entries;
